using R2API;
namespace SvenMod
{
    internal static class SvenTokens
    {
        internal static void Init()
        {
            Add("NAME","Sven","斯温");Add("SUBTITLE","The Rogue Knight","流浪剑客");
            Add("DESCRIPTION","Sven is a heavily armored swordsman who breaks enemy formations with sweeping strikes. The Rogue Knight brings his own code to Petrichor V, settling every dispute with an enormous blade.<style=cSub>\n\n< ! > Great Cleave cuts through groups. Echo Sabre adds a quick second strike.\n\n< ! > Storm Hammer stuns enemies at range. Its Scepter variant carries you into the fight, protected during flight.\n\n< ! > Warcry grants armor and speed; its Shard variant trades armor for a barrier. With Blink Dagger, cast while sprinting to reposition.\n\n< ! > God's Strength empowers sustained attacks. Momentum Cleave turns movement into two sweeping spins; Black King Bar protects either special from crowd control.</style>","斯温是一名身披重甲的剑士，擅长以大范围斩击击溃敌群。流浪剑客将自己的信条带到了琼泥V，用手中巨剑为争端作出裁决。<style=cSub>\n\n< ! > 巨力挥舞适合迎击密集的敌群，回音战刃可追加一次快速挥砍。\n\n< ! > 风暴之拳能远距离眩晕敌群；神杖版本可带你冲入战场，并在飞行中保护你。\n\n< ! > 战吼提供护甲和移速，魔晶版本则以屏障替代护甲。携带闪烁匕首时，可在疾跑中施放战吼来调整位置。\n\n< ! > 神之力量强化连续挥砍，顺势重斩则适合高速切入后旋斩清场。黑皇杖能在施放这两种特殊技能时提供短暂的控制免疫。</style>");
            Add("OUTRO_FLAVOR","...and so he left, his own law written in steel.","……于是他离开了，用钢铁书写自己的法则。");
            Add("OUTRO_FAILURE","...and so he vanished, a rogue knight without a cause.","……于是他消失了，流浪剑客再无归途。");
            Add("RELIC_TITLE","Exclusive Relic","专属装备");Add("SKIN_DEFAULT_NAME","Sven","斯温");Add("SKIN_IMMORTAL_NAME","Vigil Triumph","守夜丰功");
            Skill("PRIMARY","Great Cleave","巨力挥舞","Swing your sword in a <style=cIsUtility>10m arc</style>, dealing <style=cIsDamage>300% damage</style> to all enemies in front of you.","挥舞巨剑，对前方<style=cIsUtility>10米</style>内的所有敌人造成<style=cIsDamage>300%的伤害</style>。");
            Skill("HAMMER","Storm Hammer","风暴之拳","<style=cIsDamage>Stunning</style>. Launch a fist that explodes on impact, dealing <style=cIsDamage>600% damage</style> to enemies within <style=cIsUtility>8m</style>.","<style=cIsDamage>眩晕</style>。发射一枚碰撞后爆炸的飞拳，对<style=cIsUtility>8米</style>内的敌人造成<style=cIsDamage>600%的伤害</style>。");
            Skill("AGHANIM","Storm Hammer: Aghanim's Scepter","风暴之拳·阿哈利姆神杖","<style=cIsDamage>Stunning</style>. Fly forward up to <style=cIsUtility>40m</style>, then explode for <style=cIsDamage>300% damage</style> within <style=cIsUtility>8m</style>. <style=cIsUtility>Invulnerable</style> during flight. Other skills cannot be used while flying.","<style=cIsDamage>眩晕</style>。向前飞行最多<style=cIsUtility>40米</style>，在终点引发爆炸，对<style=cIsUtility>8米</style>内的敌人造成<style=cIsDamage>300%的伤害</style>。<style=cIsUtility>飞行期间无法被攻击</style>，无法使用其他技能。");
            Skill("WARCRY","Warcry","战吼","Rally yourself and allies within <style=cIsUtility>20m</style>, granting <style=cIsHealing>100 armor</style> and <style=cIsUtility>50% movement speed</style> for <style=cIsUtility>8s</style>.","鼓舞自己和<style=cIsUtility>20米</style>内的队友，获得<style=cIsHealing>100点护甲</style>和<style=cIsUtility>50%移动速度</style>，持续<style=cIsUtility>8秒</style>。");
            Skill("SHARD","Warcry: Aghanim's Shard","战吼·阿哈利姆魔晶","Grant yourself and allies within <style=cIsUtility>20m</style> a <style=cIsHealing>temporary barrier for 50% of maximum health</style> and <style=cIsUtility>30% movement speed</style> for <style=cIsUtility>8s</style>.","为自己和<style=cIsUtility>20米</style>内的队友提供相当于<style=cIsHealing>50%最大生命值的临时屏障</style>，并提高<style=cIsUtility>30%移动速度</style>，持续<style=cIsUtility>8秒</style>。");
            Skill("STRENGTH","God's Strength","神之力量","Sven gets pumped up! For <style=cIsUtility>10s</style>, increase Great Cleave and Echo Sabre damage to <style=cIsDamage>300% of normal</style>.","流浪剑客这下牛B了，释放神之力量，持续<style=cIsUtility>10秒</style>。巨力挥舞及回音战刃的追加挥砍造成的伤害提高至<style=cIsDamage>原来的3倍</style>。");
            Skill("MOMENTUM","Momentum Cleave","顺势重斩","<style=cIsUtility>Heavy</style>. Sweep around yourself twice, dealing <style=cIsDamage>2x1000% damage</style> within <style=cIsUtility>20m</style>.","<style=cIsUtility>重型</style>。向周围连续旋斩两圈，对<style=cIsUtility>20米</style>内的敌人造成<style=cIsDamage>2×1000%的伤害</style>。");
            Skill("ECHO","Echo Sabre","回音战刃","Every <style=cIsUtility>3s</style>, Great Cleave strikes <style=cIsDamage>twice</style> in quick succession.","每<style=cIsUtility>3秒</style>，巨力挥舞会快速挥砍<style=cIsDamage>两次</style>。");
            Skill("BLINK","Blink Dagger","闪烁匕首","After <style=cIsUtility>3s without taking damage</style>, casting Warcry while sprinting also <style=cIsUtility>teleports</style> you up to <style=cIsUtility>30m</style> toward your aim.","连续<style=cIsUtility>3秒未受到伤害</style>后，在疾跑时施放战吼，还会向瞄准方向<style=cIsUtility>传送</style>最多<style=cIsUtility>30米</style>。");
            Skill("BKB","Black King Bar","黑皇杖","Using your special skill <style=cIsUtility>cleanses debuffs and damage over time</style>, then grants <style=cIsUtility>immunity to stuns, freezes, slows and knockback</style>: <style=cIsUtility>6s</style> with God's Strength or <style=cIsUtility>2s</style> with Momentum Cleave.","使用特殊技能时<style=cIsUtility>清除负面效果和持续伤害</style>，并<style=cIsUtility>免疫眩晕、冻结、减速和击退</style>。神之力量提供<style=cIsUtility>6秒</style>免疫，顺势重斩提供<style=cIsUtility>2秒</style>免疫。");
        }
        private static void Add(string key,string en,string zh){LanguageAPI.Add("SVEN_"+key,en,"en");LanguageAPI.Add("SVEN_"+key,zh,"zh-CN");}
        private static void Skill(string key,string en,string zh,string desc,string chinese){Add(key+"_NAME",en,zh);Add(key+"_DESC",desc,chinese);}
    }
}
